jobs = []
for k, (asp, pr) in P.items():
    for tag, seed in (("take_a", 1984), ("take_b", 640)):
        jobs.append(["nb", k, "--tag", tag, "--aspect", asp, "--seed", str(seed), "--prompt", pr])
pathlib.Path(__file__).with_suffix(".json").write_text(json.dumps(jobs, indent=1))
